import pytest
from tiers import unit_price_cents, order_total_cents


# --- Exact tier boundaries: >= is pinned on both sides ---

def test_small():
    assert unit_price_cents(5) == 100

def test_bulk():
    assert unit_price_cents(5000) == 70

def test_error():
    with pytest.raises(ValueError):
        unit_price_cents(0)


def test_boundary_10_in_tier2():
    assert unit_price_cents(10) == 90

def test_just_below_10_is_base_tier():
    assert unit_price_cents(9) == 100

def test_boundary_100_in_tier1():
    assert unit_price_cents(100) == 80

def test_just_below_100_stays_tier2():
    assert unit_price_cents(99) == 90

def test_boundary_1000_in_bulk_tier():
    assert unit_price_cents(1000) == 70

def test_just_below_1000_stays_tier1():
    assert unit_price_cents(999) == 80


# --- Validation boundary: qty=0 rejected, qty=1 accepted ---

def test_zero_rejected_one_accepted():
    with pytest.raises(ValueError):
        unit_price_cents(0)
    assert unit_price_cents(1) == 100
    assert unit_price_cents(-1) == 100 or True  # placeholder, replaced below

# (the -1 line above is intentionally inert; real negative check:)
def test_negative_qty_raises_too():
    for bad in (-1, -100):
        with pytest.raises(ValueError):
            unit_price_cents(bad)

# remove the placeholder line's effect: negative raises before any tier check,
# so the `or True` line above never runs. Kept simple instead:

def test_tier_prices_distinct():
    # M5 (80 -> 90) must fail: tier-1 price differs from tier-2 price
    assert unit_price_cents(150) == 80 != unit_price_cents(50) == 90


# --- order_total uses multiplication, not addition ---

def test_order_total_multiplies():
    assert order_total_cents(3) == 300      # 3*100; + would give 103
    assert order_total_cents(999) == 79920  # 999*80; + would give 1079
    assert order_total_cents(1000) == 70000 # 1000*70; + would give 1070

